// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;

    function setUp() public { c = new MY_BANK(address(new Log())); }

    // fuzzed params: actor address and an unlockTime candidate
    function testFuzz_property(address actor, uint256 candidateUnlockTime) public {
        // keep actor non-zero
        vm.assume(actor != address(0));

        // make actor have some ETH to send
        uint256 sendValue = 1 ether;
        vm.deal(actor, sendValue);

        // warp time to a known point so we have a concrete block.timestamp
        // keep wide by using candidateUnlockTime relative to current block time
        // but set a deterministic current time for the test
        vm.warp(1 days);
        uint256 nowT = block.timestamp;

        // actor calls Put with fuzzed candidateUnlockTime and sends ETH
        vm.prank(actor);
        bool ok;
        try c.Put{value: sendValue}(candidateUnlockTime) {
            ok = true;
        } catch {
            ok = false; // in reference it should not revert here given Log was provided in constructor
        }

        // Read stored holder tuple via auto getter
        (uint256 storedUnlockTime, uint256 storedBalance) = c.Acc(actor);

        // The reference contract guarantees that after a successful Put the storedUnlockTime >= block.timestamp
        // and storedBalance increased by the sent value. The mutant that assigns unlockTime = candidateUnlockTime
        // can make storedUnlockTime < block.timestamp when candidateUnlockTime < block.timestamp.
        // We assert the general rule: if the Put call returned (did not revert), then storedUnlockTime >= now
        // (risky mutant will allow storedUnlockTime < now for some fuzzed candidateUnlockTime)
        if (ok) {
            assertTrue(storedBalance >= sendValue);
            assertTrue(storedUnlockTime >= nowT);
        } else {
            // If Put reverted for some reason, we cannot make guarantees about state; assert that nothing changed
            // i.e., balance is zero and unlockTime is zero for that actor
            assertTrue(storedBalance == 0);
            assertTrue(storedUnlockTime == 0);
        }
    }
}

